import { onCircuitBreakerTransition } from './circuit-breaker-alerts';

import { governanceLog } from '../_core/logger';
/**
 * Circuit Breaker for LLM and External Service Calls
 * 
 * Implements the circuit breaker pattern with three states:
 * - CLOSED: Normal operation, requests pass through
 * - OPEN: Failures exceeded threshold, requests short-circuit to fallback
 * - HALF_OPEN: Testing if service recovered, limited requests pass through
 * 
 * Used across all governance subsystems to prevent cascading failures
 * when LLM APIs are slow or unavailable.
 */

export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerConfig {
  /** Name for logging and tracing */
  name: string;
  /** Max failures before opening circuit (default: 3) */
  failureThreshold?: number;
  /** Time in ms before attempting recovery (default: 30000) */
  recoveryTimeout?: number;
  /** Timeout in ms for individual calls (default: 10000) */
  callTimeout?: number;
  /** Max concurrent calls in half-open state (default: 1) */
  halfOpenMaxCalls?: number;
}

export interface CircuitBreakerMetrics {
  name: string;
  state: CircuitState;
  failures: number;
  successes: number;
  totalCalls: number;
  lastFailure: number | null;
  lastSuccess: number | null;
  lastStateChange: number;
  fallbacksUsed: number;
  averageLatency: number;
}

interface CircuitBreakerInternals {
  state: CircuitState;
  failures: number;
  successes: number;
  totalCalls: number;
  lastFailure: number | null;
  lastSuccess: number | null;
  lastStateChange: number;
  fallbacksUsed: number;
  halfOpenCalls: number;
  latencies: number[];
}

const MAX_BREAKER_INSTANCES = 256;
const MAX_LATENCY_WINDOW = 100;
const MAX_BREAKER_NAME_LENGTH = 128;
const VALID_BREAKER_NAME_RE = /^[a-zA-Z0-9._-]+$/;

const breakers = new Map<string, CircuitBreakerInternals>();

