    throw new Error(
      `CircuitBreaker name must be 1-${MAX_BREAKER_NAME_LENGTH} alphanumeric/dash/underscore characters, got: ${JSON.stringify(String(config.name ?? '').slice(0, 100))}`
    );
  }

  const existing = breakers.get(config.name);
  if (existing) return existing;

